head.b:skin:
:root {
    --primary-color: #2563eb;
    --primary-hover: #1d4ed8;
    --bg-color: #ffffff;
    --secondary-bg: #f8fafc;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --card-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --header-height: 70px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    margin: 0; padding: 0;
    line-height: 1.6;
}

/* Scroll Progress Bar */
#scroll-progress {
    position: fixed; top: 0; left: 0; width: 0%; height: 4px;
    background: var(--primary-color); z-index: 1001; transition: width 0.1s;
}

/* Header & Navigation */
header {
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border-color);
    height: var(--header-height);
    position: fixed; width: 100%; top: 0; z-index: 1000;
    display: flex; align-items: center;
}
.header-inner {
    width: 92%; max-width: 1200px; margin: 0 auto;
    display: flex; justify-content: space-between; align-items: center;
}
.logo { font-size: 1.5rem; font-weight: 800; color: var(--primary-color); text-decoration: none; letter-spacing: -0.5px; }

nav ul { list-style: none; display: flex; gap: 25px; margin: 0; padding: 0; }
nav ul li a { text-decoration: none; color: var(--text-main); font-weight: 500; font-size: 0.95rem; transition: color 0.3s; }
nav ul li a:hover { color: var(--primary-color); }

.mobile-menu-toggle { display: none; font-size: 1.5rem; cursor: pointer; color: var(--text-main); }

@media (max-width: 768px) {
    nav.mobile-active {
        display: block !important;
        position: absolute;
        top: var(--header-height);
        left: 0;
        width: 100%;
        background: #fff;
        border-bottom: 1px solid var(--border-color);
        padding: 20px;
        animation: slideDown 0.3s ease-out;
    }
    nav.mobile-active ul {
        flex-direction: column;
        gap: 15px;
    }
}

@keyframes slideDown {
    from { transform: translateY(-10px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

/* Main Container */
.main-wrapper {
    max-width: 1200px; width: 92%; margin: calc(var(--header-height) + 40px) auto 60px;
    display: grid; grid-template-columns: 1fr 320px; gap: 40px;
}

/* Content Area */
.content-area { min-width: 0; }

/* Post Grid */
.posts-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 30px; }

.post-card {
    background: #fff; border: 1px solid var(--border-color); border-radius: 12px;
    overflow: hidden; transition: transform 0.3s, box-shadow 0.3s;
    text-decoration: none; color: inherit; display: flex; flex-direction: column;
    opacity: 0; transform: translateY(20px); /* For animation */
}
.post-card.visible { opacity: 1; transform: translateY(0); }
.post-card:hover { transform: translateY(-5px); box-shadow: var(--card-shadow); }

.card-img { width: 100%; height: 200px; object-fit: cover; background: var(--secondary-bg); }
.card-body { padding: 20px; flex-grow: 1; }
.card-meta { font-size: 0.75rem; color: var(--text-muted); margin-bottom: 8px; text-transform: uppercase; font-weight: 600; }
.card-title { font-size: 1.25rem; font-weight: 700; margin: 0 0 10px; line-height: 1.3; color: var(--text-main); }
.card-excerpt { font-size: 0.9rem; color: var(--text-muted); line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

/* Single Post */
.single-post-header { margin-bottom: 30px; }
.single-post-title { font-size: 2.5rem; font-weight: 800; margin-bottom: 15px; line-height: 1.2; }
.post-body { font-size: 1.1rem; line-height: 1.8; color: #334155; }
.post-body h2 { font-size: 1.75rem; margin-top: 40px; }
.post-body img { max-width: 100%; height: auto; border-radius: 12px; margin: 20px 0; }

/* Sidebar */
.sidebar-widget { margin-bottom: 40px; }
.widget-title { font-size: 1.1rem; font-weight: 700; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 2px solid var(--primary-color); display: inline-block; }

.popular-posts ul { list-style: none; padding: 0; }
.popular-posts li { display: flex; gap: 15px; margin-bottom: 15px; }
.pop-img { width: 60px; height: 60px; border-radius: 8px; object-fit: cover; flex-shrink: 0; }
.pop-title { font-size: 0.9rem; font-weight: 600; color: var(--text-main); text-decoration: none; }

/* Loading Skeleton */
.skeleton { background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%); background-size: 200% 100%; animation: loading 1.5s infinite; }
@keyframes loading { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

/* Footer */
footer { background: var(--secondary-bg); padding: 60px 0 30px; border-top: 1px solid var(--border-color); margin-top: 80px; }
.footer-inner { max-width: 1200px; width: 92%; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 40px; }
.footer-logo { font-size: 1.5rem; font-weight: 800; color: var(--primary-color); text-decoration: none; margin-bottom: 20px; display: block; }
.footer-links h4 { margin-bottom: 20px; font-weight: 700; }
.footer-links ul { list-style: none; padding: 0; }
.footer-links li { margin-bottom: 10px; }
.footer-links a { text-decoration: none; color: var(--text-muted); font-size: 0.9rem; transition: color 0.3s; }
.footer-links a:hover { color: var(--primary-color); }
.footer-bottom { border-top: 1px solid var(--border-color); margin-top: 40px; padding-top: 20px; text-align: center; color: var(--text-muted); font-size: 0.85rem; }

/* Responsive */
@media (max-width: 992px) {
    .main-wrapper { grid-template-columns: 1fr; }
    .sidebar { order: 2; }
}
@media (max-width: 768px) {
    .single-post-title { font-size: 1.8rem; }
    nav { display: none; }
    .mobile-menu-toggle { display: block; }
}

/* AdSense Placeholders */
.ad-slot { background: var(--secondary-bg); border: 1px dashed var(--border-color); padding: 20px; text-align: center; color: var(--text-muted); font-size: 0.8rem; margin: 20px 0; border-radius: 8px; }

body.script:
//
    // Mobile Menu Toggle
    const menuToggle = document.querySelector('.mobile-menu-toggle');
    const nav = document.querySelector('nav');
    menuToggle.addEventListener('click', () => {
        nav.classList.toggle('mobile-active');
        const icon = menuToggle.querySelector('i');
        icon.classList.toggle('fa-bars');
        icon.classList.toggle('fa-times');
    });

    // Scroll Progress Bar
    window.onscroll = function() {
        let winScroll = document.body.scrollTop || document.documentElement.scrollTop;
        let height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        let scrolled = (winScroll / height) * 100;
        document.getElementById("scroll-progress").style.width = scrolled + "%";
    };

    // Fade-in Animation on Scroll
    const observerOptions = { threshold: 0.1 };
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
            }
        });
    }, observerOptions);

    document.querySelectorAll('.post-card').forEach(card => observer.observe(card));

    // Schema Markup Injection (Article + Breadcrumb)
    if (window.location.pathname.includes('/20') || window.location.pathname.includes('.html')) {
        const isPost = window.location.pathname.includes('/20');
        const schemas = [];

        if (isPost) {
            schemas.push({
                "@context": "https://schema.org",
                "@type": "TechArticle",
                "headline": document.title,
                "image": document.querySelector('img.card-img')?.src || "",
                "author": { "@type": "Person", "name": "TechVantage Team" },
                "publisher": {
                    "@type": "Organization",
                    "name": "TechVantage",
                    "logo": { "@type": "ImageObject", "url": "" }
                }
            });
        }

        // Breadcrumb Schema
        const pathParts = window.location.pathname.split('/').filter(p => p);
        const breadcrumb = {
            "@context": "https://schema.org",
            "@type": "BreadcrumbList",
            "itemListElement": [{
                "@type": "ListItem",
                "position": 1,
                "name": "Home",
                "item": window.location.origin
            }]
        };

        pathParts.forEach((part, index) => {
            breadcrumb.itemListElement.push({
                "@type": "ListItem",
                "position": index + 2,
                "name": part.replace('.html', '').replace(/-/g, ' '),
                "item": window.location.origin + '/' + pathParts.slice(0, index + 1).join('/')
            });
        });
        schemas.push(breadcrumb);

        schemas.forEach(s => {
            const script = document.createElement('script');
            script.type = 'application/ld+json';
            script.text = JSON.stringify(s);
            document.head.appendChild(script);
        });
    }
//
